%[text] ## Demo3: Feedforward Control Experiment
%%
%[text] ### STEP 1: DESIGN FEEDBACK CONTROLLER
%[text] load settings for the experiment
omega = 15; % desired pole [rad/s], not [Hz]
Smax = 2; % maximum gain of sensitivity function, 6 dB

% Student-tunable FF gains. [] selects the nominal-model compensation
% Kfa=Jn, Kfv=Dn, Kfc=0 after plant.mat is loaded.
Kfa = [];
Kfv = [];
Kfc = [];

repeat_count = 1;
hold_margin_s = 1.0;
save_results = true;

cfg = experiment.ExperimentConfig.defaults();
plant_mat_path = fullfile(experiment.scenario.default_result_dir(), "plant.mat");
plant_data = experiment.exp0n.load_plant_data( ...
  plant_mat_path, "expected_sample_time_s", 1 / cfg.env.task_rate_hz);
Pd = plant_data.Pd;
Pdn = plant_data.Pdn;
Jn = plant_data.Jn;
Dn = plant_data.Dn;
Ts = plant_data.Ts;
%%
%[text] design FB controller
%[text] (hint: during tuning of FF input the designed FB controller in demo2 may not be optimal)
Kpid = experiment.exp02.designpid(Dn/Jn, 0, 1/Jn, omega);
Kd = c2d(Kpid, Ts, "tustin"); % digital feedback controller
% load(fullfile(experiment.scenario.default_result_dir(), "feedback_result.mat"), "Kd"); % reuse Demo2 controller

trajectory = experiment.exp0n.load_trajectory( ...
  "expected_sample_time_s", Ts, "table_max_n", cfg.env.table_max_n);
scenario = experiment.scenario.exp03( ...
  plant_data, trajectory, "cfg", cfg, "omega", omega, "Smax", Smax, ...
  "Kd", Kd, "Kfa", Kfa, "Kfv", Kfv, "Kfc", Kfc, ...
  "repeat_count", repeat_count, "hold_margin_s", hold_margin_s, ...
  "save_results", save_results);
%%
%[text] ### Check the stability and performance of FB Controller (Always check before experiment!!!)
%[text] use nyquist and sensitivity plot
%[text] (note: Pd is actual system, Pdn is modelled system)
stability = experiment.exp02.stability_check( ... %[output:group:4c27522b] %[output:4b0407d4] %[output:3b0a0e08]
  Pd, Pdn, Kd, Smax, ... %[output:4b0407d4] %[output:3b0a0e08]
  "error_id", "experiment:exp03_feedforward:sensitivityLimitExceeded"); %[output:group:4c27522b] %[output:4b0407d4] %[output:3b0a0e08]
stability_summary = table( ...
  stability.max_sensitivity, Smax, stability.limit_exceeded, ...
  VariableNames=["measuredSensitivityPeak", "limit", "limitExceeded"]);
display(stability_summary); %[output:097921d7]
%%
%[text] ### STEP 2: FEEDFORWARD EXPERIMENT
%[text] set reference trajectory
t = trajectory.t;
r = trajectory.p;
v = trajectory.v;
a = trajectory.a;
N = numel(r);

figure; %[output:96c7bf74]
subplot(3, 1, 1); %[output:96c7bf74]
plot(t, r, "b"); %[output:96c7bf74]
grid off; %[output:96c7bf74]
xlabel("Time [s]"); ylabel("Position [rad]"); %[output:96c7bf74]
subplot(3, 1, 2); %[output:96c7bf74]
plot(t, v, "b"); %[output:96c7bf74]
grid off; %[output:96c7bf74]
xlabel("Time [s]"); ylabel("Velocity [rad/s]"); %[output:96c7bf74]
subplot(3, 1, 3); %[output:96c7bf74]
plot(t, a, "b"); %[output:96c7bf74]
grid off; %[output:96c7bf74]
xlabel("Time [s]"); ylabel("Acceleration [rad/s^2]"); %[output:96c7bf74]
%%
%[text] ### **Design Feedforward input**
Kfa = scenario.feedforward_gains.Kfa;
Kfv = scenario.feedforward_gains.Kfv;
Kfc = scenario.feedforward_gains.Kfc;
f = scenario.feedforward;
%%
%[text] execute the VirtualMotor experiment through the shared workflow
workflow = experiment.workflow.run_exp03(scenario);
signals = workflow.signals;
feedforward_metrics = workflow.metrics;
y = signals.position_act(:);
e = signals.error(:);
u = signals.control_input(:);

expected_log_n = N * repeat_count;
t = (0:expected_log_n-1)' * Ts;
r = repmat(r, repeat_count, 1);
f = repmat(f, repeat_count, 1);

%%
%[text] save experiment data
completed_at_utc = string(datetime("now", "TimeZone", "UTC", ...
  "Format", "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"));
artifact_summary = table( ...
  workflow.artifacts.saved, string(workflow.artifacts.result), ...
  completed_at_utc, ...
  VariableNames=["saved", "feedforwardResult", "completedAtUtc"]);
display(artifact_summary); %[output:978302b1]
%%
%[text] ### STEP 3: Analyze the results of the experiment
%[text] download data
%%
%[text] plot tracking result of feedforward control
figure; %[output:7879e103]
subplot(3, 1, 1); %[output:7879e103]
plot(t, r, t, y); %[output:7879e103]
xlabel("Time [s]"); ylabel("Position [rad]"); %[output:7879e103]
grid on; %[output:7879e103]

subplot(3, 1, 2); %[output:7879e103]
plot(t, e); %[output:7879e103]
xlabel("Time [s]"); ylabel("Tracking error [rad]"); %[output:7879e103]
grid on; %[output:7879e103]

subplot(3, 1, 3); %[output:7879e103]
plot(t, signals.applied_feedforward); hold on; ... %[output:7879e103]
plot(t, signals.feedback_input); hold off; %[output:7879e103]
xlabel("Time [s]"); ylabel("Input [A]"); %[output:7879e103]
legend("FF", "FB"); %[output:7879e103]
grid on; %[output:7879e103]
%%
%[text] display tracking metrics
tracking_summary = table( ...
  feedforward_metrics.tracking_error_l2, ...
  feedforward_metrics.tracking_error_rms, ...
  feedforward_metrics.tracking_error_peak, ...
  feedforward_metrics.max_abs_feedforward, ...
  feedforward_metrics.max_abs_current_cmd, ...
  VariableNames=["errorL2", "errorRMS", "errorPeak", ...
    "maxFeedforward_A", "maxTotalInput_A"]);
display(tracking_summary); %[output:6f6ea238]



